55	+uint64_t elf_load_top(const std::string& elf_path, std::string& err) {
56	+  err.clear();
57	+  std::vector<char> buf;
58	+  if (!slurp(elf_path, buf)) {
59	+    err = "cannot read ELF '" + elf_path + "'";
60	+    return 0;
61	+  }
62	+  Elf64_Ehdr eh;
63	+  if (!load(buf, 0, eh) || std::memcmp(eh.e_ident, ELFMAG, SELFMAG) != 0) {
64	+    err = "not an ELF file: " + elf_path;
65	+    return 0;
66	+  }
67	+  if (eh.e_ident[EI_CLASS] != ELFCLASS64) {
68	+    err = "not an RV64 (ELFCLASS64) file: " + elf_path;
69	+    return 0;
70	+  }
71	+  // Top of the static image: the highest (p_paddr + p_memsz) over PT_LOAD.
72	+  // p_paddr is the guest-physical placement (== p_vaddr for the identity-mapped
73	+  // bare-metal fixtures), the space the V-scratch GPA also lives in.
74	+  uint64_t top = 0;
75	+  for (uint16_t i = 0; i < eh.e_phnum; ++i) {
76	+    Elf64_Phdr ph;
77	+    const size_t off = static_cast<size_t>(eh.e_phoff) +
78	+                       static_cast<size_t>(i) * eh.e_phentsize;
79	+    if (!load(buf, off, ph)) {
80	+      err = "truncated program header table in '" + elf_path + "'";
81	+      return 0;
82	+    }
83	+    if (ph.p_type != PT_LOAD) continue;
84	+    const uint64_t end = ph.p_paddr + ph.p_memsz;
85	+    if (end > top) top = end;
86	+  }
87	+  return top;  // 0 (empty err) when the ELF has no loadable segments
88	+}
