20	// Free bytes on the filesystem holding `dir`, or -1 if it does not exist.
21	long long free_bytes(const std::string& dir) {
22	  struct statvfs vfs;
23	  if (statvfs(dir.c_str(), &vfs) != 0) return -1;
24	  return static_cast<long long>(vfs.f_bavail) *
25	         static_cast<long long>(vfs.f_frsize);
26	}
