55	long long parse_size(const std::string& spec, std::string& err) {
56	  static const std::regex re(R"(\s*(\d+(?:\.\d+)?)\s*([KMGT]?)\s*)",
57	                             std::regex::icase);
58	  std::smatch m;
59	  if (!std::regex_match(spec, m, re)) {
60	    err = "invalid mmap size '" + spec +
61	          "': expected <number>[K|M|G|T] (e.g. '128M', '8G', '1024')";
62	    return 0;
63	  }
64	  const double num = std::stod(m[1].str());
65	  long long mult = 1;
66	  if (m[2].length()) {
67	    switch (std::toupper(static_cast<unsigned char>(m[2].str()[0]))) {
68	      case 'K': mult = 1024LL; break;
69	      case 'M': mult = 1024LL * 1024; break;
70	      case 'G': mult = 1024LL * 1024 * 1024; break;
71	      case 'T': mult = 1024LL * 1024 * 1024 * 1024; break;
72	    }
73	  }
74	  // Truncate toward zero like Python int(float(num) * multiplier).
75	  const long long size =
76	      static_cast<long long>(num * static_cast<double>(mult));
77	  if (size <= 0) {
78	    err = "invalid mmap size '" + spec + "': must be > 0";
79	    return 0;
80	  }
81	  err.clear();
82	  return size;
83	}
84	
85	// L26/F2: physical mmap = program RAM + one V-scratch page. See shm.hpp.
86	long long physical_mmap_bytes(long long program_bytes) {
87	  return program_bytes + HYBRID_V_SCRATCH_BYTES;
88	}
89	
90	long long max_program_mem_bytes() {
91	  // AE350 DRAM window is 2 GiB; leave room for the scratch page on top.
92	  constexpr long long kAe350DramWindowBytes = 2LL * 1024 * 1024 * 1024;
93	  return kAe350DramWindowBytes - HYBRID_V_SCRATCH_BYTES;
94	}
