119	std::vector<std::string> qemu_m_args(const std::string& spec,
120	                                     std::string& err) {
121	  err.clear();
122	  if (spec.empty()) return {};
123	  const long long bytes = parse_size(spec, err);
124	  if (!err.empty()) {
125	    err = "--mem-size: " + err;
126	    return {};
127	  }
128	  if (bytes % (1024 * 1024) != 0) {
129	    err = "--mem-size '" + spec +
130	          "': QEMU's -m takes whole MiB; round to a multiple of 1M";
131	    return {};
132	  }
133	  return {"-m", std::to_string(bytes / (1024 * 1024)) + "M"};
134	}
