136	MmapDirChoice resolve_mmap_dir(
137	    const std::vector<MmapTier>& tiers, long long size,
138	    const std::function<long long(const std::string&)>& probe,
139	    std::string& err) {
140	  const long long need = size + kMmapSafetyMargin;
141	  std::vector<std::string> reasons;
142	  for (const MmapTier& t : tiers) {
143	    const long long free = probe(t.dir);
144	    if (free >= need) {
145	      err.clear();
146	      std::string note;
147	      for (size_t i = 0; i < reasons.size(); i++)
148	        note += (i ? "; " : "") + reasons[i];
149	      return {t.dir, note};
150	    }
151	    reasons.push_back(free < 0 ? t.label + " missing"
152	                               : t.label + " too small (" +
153	                                     format_bytes(free) + " free)");
154	  }
155	  err = "no mmap directory can hold " + format_bytes(size) +
156	        " + 256 MiB margin: ";
157	  for (size_t i = 0; i < reasons.size(); i++)
158	    err += (i ? "; " : "") + reasons[i];
159	  err += "; set HSIM_MMAP_DIR to a directory with enough free space";
160	  return {"", ""};
161	}
