163	std::vector<MmapTier> mmap_tiers() {
164	  if (const char* pinned = std::getenv("HSIM_MMAP_DIR"); pinned && pinned[0])
165	    return {{pinned, "HSIM_MMAP_DIR='" + std::string(pinned) + "'"}};
166	
167	  std::string cache;
168	  if (const char* xdg = std::getenv("XDG_CACHE_HOME"); xdg && xdg[0])
169	    cache = std::string(xdg) + "/andes-sim";
170	  else if (const char* home = std::getenv("HOME"); home && home[0])
171	    cache = std::string(home) + "/.cache/andes-sim";
172	
173	  std::vector<MmapTier> tiers = {{"/dev/shm", "/dev/shm"}};
174	  if (!cache.empty()) {
175	    std::error_code ec;
176	    std::filesystem::create_directories(cache, ec);  // probe needs it to exist
177	    tiers.push_back({cache, cache});
178	  }
179	  return tiers;
180	}
