182	std::string allocate(long long size, std::string& err,
183	                     const std::string& prefix) {
184	  const MmapDirChoice choice =
185	      resolve_mmap_dir(mmap_tiers(), size, free_bytes, err);
186	  if (choice.dir.empty()) return "";
187	
188	  std::string tmpl = choice.dir + "/" + prefix + "XXXXXX";
189	  std::vector<char> buf(tmpl.begin(), tmpl.end());
190	  buf.push_back('\0');
191	  const int fd = mkstemp(buf.data());
192	  if (fd < 0) {
193	    err = "failed to create mmap file in " + choice.dir;
194	    return "";
195	  }
196	  close(fd);
197	  const std::string path(buf.data());
198	  if (truncate(path.c_str(), size) != 0) {
199	    unlink(path.c_str());
200	    err = "failed to size mmap file " + path;
201	    return "";
202	  }
203	
204	  std::string line = "[hsim mmap] " + format_bytes(size) + " at " +
205	                     choice.dir + " (free: " + format_bytes(free_bytes(choice.dir)) + ")";
206	  if (!choice.note.empty()) line += " (fallback: " + choice.note + ")";
207	  std::printf("%s\n", line.c_str());
208	  std::fflush(stdout);
209	  err.clear();
210	  return path;
211	}
