41	LegTriggerArgs leg_trigger_args(const Trigger& t, const std::string& role,
42	                                std::string& err) {
43	  err.clear();
44	  LegTriggerArgs out;
45	  if (t.kind == "marker") return out;  // markers detected by plugin/vsim, not argv
46	
47	  const bool fast = role == "fast-leg";
48	  const bool accurate = role == "accurate-leg";
49	  if (!fast && !accurate) return out;  // other roles carry no trigger args
50	
51	  // Required-param lookup. A missing key is a caller bug; surface it (don't
52	  // throw) so plan_argvs can report which step failed.
53	  auto param = [&](const char* key) -> const std::string* {
54	    auto it = t.params.find(key);
55	    if (it == t.params.end()) {
56	      err = "trigger '" + t.kind + "' missing param '" + key + "'";
57	      return nullptr;
58	    }
59	    return &it->second;
60	  };
61	
62	  if (t.kind == "pc") {
63	    if (fast) {
64	      if (const std::string* p = param("enter_pc"))
65	        out.plugin_suffix = ",enter_pc=" + *p;
66	    } else if (const std::string* p = param("exit_pc")) {
67	      out.extra = {"--hybrid-exit-pc", *p};
68	    }
69	    return out;
70	  }
71	  if (t.kind == "icount") {
72	    if (fast) {
73	      if (const std::string* p = param("qemu_icount"))
74	        out.plugin_suffix = ",icount=" + *p;
75	    } else if (const std::string* p = param("vsim_icount")) {
76	      out.extra = {"--hybrid-icount", *p};
77	    }
78	    return out;
79	  }
80	
81	  // verify oracle leg (verify_oracle F4): a pure-QEMU drain at the ROI exit
82	  // boundary, sampling at vsim's actual halt pc (drain_pc -- the DMI halt
83	  // lands a few insns past the trigger, and the comparison is only valid at
84	  // the same architectural point). qemu-only: the oracle plan has no
85	  // accurate leg.
86	  if (t.kind == "verify-marker" || t.kind == "verify-pc") {
87	    if (!fast) return out;
88	    std::string suffix = ",exit_marker=1";
89	    if (t.kind == "verify-pc") {
90	      const std::string* p = param("exit_pc");
91	      if (!p) return out;
92	      suffix = ",exit_pc=" + *p;
93	    }
94	    if (const std::string* p = param("drain_pc"))
95	      out.plugin_suffix = suffix + ",drain_pc=" + *p;
96	    return out;
97	  }
98	
99	  // cosim oracle leg (cosim_roi F4): pure QEMU arms at the ROI entry and
100	  // drains at the vsim checkpoints' retire deltas (`counts`, pre-joined
101	  // "a:b:c"; the last entry is the final exit-state drain). qemu-only: the
102	  // oracle plan has no accurate leg.
103	  if (t.kind == "cosim-marker" || t.kind == "cosim-pc") {
104	    if (!fast) return out;
105	    std::string suffix = ",cosim_marker=1";
106	    if (t.kind == "cosim-pc") {
107	      const std::string* p = param("enter_pc");
108	      if (!p) return out;
109	      suffix = ",cosim_pc=" + *p;
110	    }
111	    if (const std::string* p = param("counts"))
112	      out.plugin_suffix = suffix + ",cosim_counts=" + *p;
113	    return out;
114	  }
115	
116	  err = "unknown trigger kind '" + t.kind + "'";
117	  return out;
118	}
