120	std::vector<std::vector<std::string>> plan_argvs(
121	    const Plan& plan, const std::vector<EngineDescriptor>& engines,
122	    const std::string& workdir, const RuntimeCtx& ctx, std::string& err) {
123	  std::vector<std::vector<std::string>> out;
124	  out.reserve(plan.steps.size());
125	  std::string prev_state_out;  // empty for the cold first leg
126	
127	  // hw-config sync: {vlen} comes from the accurate-leg engine's descriptor.
128	  long vlen = 0;
129	  for (const Step& s : plan.steps)
130	    if (s.role == "accurate-leg")
131	      if (const EngineDescriptor* e = find_engine(engines, s.engine_id))
132	        if (e->vlen > 0) vlen = e->vlen;
133	  const std::string vlen_str = std::to_string(synced_vlen(vlen));
134	
135	  for (size_t i = 0; i < plan.steps.size(); ++i) {
136	    const Step& step = plan.steps[i];
137	    const EngineDescriptor* eng = find_engine(engines, step.engine_id);
138	    if (!eng) {
139	      err = "plan step " + std::to_string(i) + ": unknown engine '" +
140	            step.engine_id + "'";
141	      return {};
142	    }
143	    const std::vector<std::string>* tmpl = eng->invoke_for(step.role);
144	    if (!tmpl) {
145	      err = "plan step " + std::to_string(i) + ": engine '" + step.engine_id +
146	            "' has no invoke template for role '" + step.role + "'";
147	      return {};
148	    }
149	
150	    std::string trig_err;
151	    const LegTriggerArgs lt = leg_trigger_args(step.trigger, step.role, trig_err);
152	    if (!trig_err.empty()) {
153	      err = "plan step " + std::to_string(i) + ": " + trig_err;
154	      return {};
155	    }
156	
157	    const std::string state_out = state_path(workdir, i);
158	    const std::map<std::string, std::string> m = {
159	        {"bin", eng->bin_path},
160	        {"elf", plan.elf},
161	        {"plugin", ctx.plugin_path},
162	        {"mmap", ctx.mmap_path},
163	        {"mmap_size", std::to_string(ctx.mem_size)},
164	        {"mmap_base", ctx.mmap_base},
165	        {"state_in", prev_state_out},
166	        {"state_out", state_out},
167	        {"trigger", lt.plugin_suffix},  // qemu plugin comma-suffix (empty for marker)
168	        {"vlen", vlen_str},
169	    };
170	    std::vector<std::string> argv = build_argv(*tmpl, m, err);
171	    if (!err.empty()) {
172	      err = "plan step " + std::to_string(i) + ": " + err;
173	      return {};
174	    }
175	    // Trigger's vsim tokens, then user-forwarded per-leg flags -- both verbatim
176	    // after the filled template (matches tests/e2e.sh's ordering).
177	    argv.insert(argv.end(), lt.extra.begin(), lt.extra.end());
178	    argv.insert(argv.end(), step.extra_args.begin(), step.extra_args.end());
179	    out.push_back(std::move(argv));
180	    prev_state_out = state_out;
181	  }
182	  err.clear();
183	  return out;
184	}
