186	PlanResult run_plan(const Plan& plan,
187	                    const std::vector<EngineDescriptor>& engines,
188	                    const PlanOptions& opts) {
189	  PlanResult res;
190	  if (plan.steps.empty()) {
191	    res.error = "plan has no steps";
192	    return res;
193	  }
194	
195	  // Acquire the shared mmap: allocate one (and own it) when none is pinned.
196	  std::string mmap_path = plan.mmap_path;
197	  const bool own_mmap = mmap_path.empty();
198	  if (own_mmap) {
199	    std::string err;
200	    // L26/F2: back the mmap with one V-scratch page above the program's RAM.
201	    mmap_path = allocate(physical_mmap_bytes(plan.mem_size), err);
202	    if (mmap_path.empty()) {
203	      res.error = err;
204	      return res;
205	    }
206	  }
207	
208	  // A private dir for the threaded drain files.
209	  std::error_code ec;
210	  fs::path workdir = fs::temp_directory_path(ec) / "andes-sim-plan-XXXXXX";
211	  std::string tmpl = workdir.string();
212	  std::vector<char> tbuf(tmpl.begin(), tmpl.end());
213	  tbuf.push_back('\0');
214	  const char* made = ::mkdtemp(tbuf.data());
215	  if (!made) {
216	    if (own_mmap) ::unlink(mmap_path.c_str());
217	    res.error = "failed to create plan work dir";
218	    return res;
219	  }
220	  const std::string wd = made;
221	
222	  RuntimeCtx ctx;
223	  ctx.mmap_path = mmap_path;
224	  // L26/F2: the legs (QEMU backend size, vsim --shared-mem-size) see the
225	  // PHYSICAL window -- program RAM plus the V-scratch page. The program's own
226	  // linker script still uses only --mem-size, so the scratch page sits above
227	  // everything it can address.
228	  ctx.mem_size = physical_mmap_bytes(plan.mem_size);
229	  ctx.plugin_path = resolve_plugin(opts.plugin_path);  // mmap_base keeps its "0x0" default
230	
231	  std::string err;
232	  const std::vector<std::vector<std::string>> argvs =
233	      plan_argvs(plan, engines, wd, ctx, err);
234	  if (!err.empty()) {
235	    res.error = err;
236	  } else {
237	    for (size_t i = 0; i < argvs.size(); ++i) {
238	      const RunResult r = run_process(argvs[i], opts.timeout_ms);
239	      if (r.spawn_failed) {
240	        res.error = "plan step " + std::to_string(i) + ": failed to spawn";
241	        break;
242	      }
243	      if (r.timed_out) {
244	        res.error = "plan step " + std::to_string(i) + ": timed out after " +
245	                    std::to_string(opts.timeout_ms) + " ms";
246	        break;
247	      }
248	      if (r.rc != opts.expect_rc) {
249	        res.error = "plan step " + std::to_string(i) + ": expected exit " +
250	                    std::to_string(opts.expect_rc) + ", got " +
251	                    std::to_string(r.rc);
252	        break;
253	      }
254	      const StateFile sf = read_state_file(state_path(wd, i));
255	      if (!sf.ok()) {
256	        res.error = "plan step " + std::to_string(i) + ": " + sf.error;
257	        break;
258	      }
259	      // cosim checkpoints (`<state_out>.ckpts` stream, cosim_redesign F3):
260	      // read them back now, before the workdir teardown deletes the file.
261	      std::vector<hybrid_state_v1> ckpts;
262	      const std::string stream_p = state_path(wd, i) + ".ckpts";
263	      if (fs::exists(stream_p, ec)) {
264	        StateStream cs = read_state_stream(stream_p);
265	        if (!cs.ok()) {
266	          res.error = "plan step " + std::to_string(i) + ": " + cs.error;
267	          break;
268	        }
269	        ckpts = std::move(cs.records);
270	      }
271	      res.phases.push_back(
272	          {sf.st.mcycle, sf.st.minstret, r.out, sf.st, std::move(ckpts)});
273	    }
274	  }
275	
276	  fs::remove_all(wd, ec);
277	  if (own_mmap) ::unlink(mmap_path.c_str());
278	  return res;
279	}
